function renderTime(){state.now=new Date();const w=windowNow(),start=state.variant==='3'?w.start3:w.start7, now=new Date();$('#month').textContent=(state.lang==='he'?({Tishrei:'תשרי',Cheshvan:'חשוון',Kislev:'כסלו',Tevet:'טבת',Shvat:'שבט',Adar:'אדר',Nisan:'ניסן',Iyyar:'אייר',Sivan:'סיוון',Tamuz:'תמוז',Av:'אב',Elul:'אלול'}[w.name]||w.name):w.name)+' · '+new HDate(w.start7).renderGematriya();$('#start').textContent=fmt(start);$('#end').textContent=fmt(w.end);$('#status').textContent=state.lang==='he'?(now<start?'עוד לא התחיל':now>w.end?'הזמן הסתיים':'בתוך הזמן המחושב'):(now<start?'Coming up':now>w.end?'Window has passed':'Within the calculated window');$('#status').className='pill '+(now>=start&&now<=w.end?'active':'');$('#alt-times').textContent=`Other opinions: 3 days from molad ${fmt(w.start3)} · 7 days ${fmt(w.start7)} · 15-day limit ${fmt(w.end15)}. Times shown for the selected location when weather data is available; otherwise in your device timezone.`;renderCompletion();const s=sky();renderCountdown();renderMoonExtras();$('#sky').textContent=state.lang==='he'?(s?`הלבנה כרגע: ${Math.round(s.alt)}° מעל האופק, ${bearingName(s.az)} (${Math.round(s.az)}°). ${s.alt<5?'הלבנה נמוכה כרגע.':s.sunAlt>-6?'ייתכן שהשמים עדיין מוארים מדי.':'בדקו שהלבנה אכן נראית בשמים.'}`:'אפשרו מיקום כדי לראות את כיוון הלבנה ושטחים פתוחים קרובים.'):s?`Moon right now: ${Math.round(s.alt)}° above horizon, ${bearingName(s.az)} (${Math.round(s.az)}°). ${s.alt<5?'Too low to rely on a clear view now.':s.sunAlt>-6?'Sky may still be too light.':'Look up and confirm you can actually see it.'}`:'Enable location to see the moon’s direction and nearby open spaces.'}
