function distance(a,b,c,d){const R=6371000,p1=a*Math.PI/180,p2=c*Math.PI/180,dp=(c-a)*Math.PI/180,dl=(d-b)*Math.PI/180;return 2*R*Math.asin(Math.sqrt(Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2))}
function bearing(a,b,c,d){const y=Math.sin((d-b)*Math.PI/180)*Math.cos(c*Math.PI/180),x=Math.cos(a*Math.PI/180)*Math.sin(c*Math.PI/180)-Math.sin(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.cos((d-b)*Math.PI/180);return(Math.atan2(y,x)*180/Math.PI+360)%360}
const mapLink=(p)=>`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.lat+','+p.lon)}&travelmode=walking`;
function localXY(lat,lon,refLat,refLon){return [(lon-refLon)*111320*Math.cos(refLat*Math.PI/180),(lat-refLat)*111320]}
function segmentCross(a,b,c,d){const cross=(u,v)=>u[0]*v[1]-u[1]*v[0],r=[b[0]-a[0],b[1]-a[1]],q=[d[0]-c[0],d[1]-c[1]],den=cross(r,q);if(Math.abs(den)<1e-10)return null;const ca=[c[0]-a[0],c[1]-a[1]],t=cross(ca,q)/den,u=cross(ca,r)/den;return t>=0&&t<=1&&u>=0&&u<=1?t:null}
function height(tags){let h=parseFloat(tags.height);if(Number.isFinite(h)&&h>0)return h;let levels=parseFloat(tags['building:levels']);return Number.isFinite(levels)&&levels>0?levels*3:null}
// Ground-level line of sight in the moon's azimuth; buildings without height are unknown.
function sightline(p,az,alt){if(alt<=0)return {status:'below',blocked:0,unknown:0,checked:0};const len=220,rad=az*Math.PI/180,endpoint=[len*Math.sin(rad),len*Math.cos(rad)],blocks=[];let unknown=0,checked=0;for(const b of state.buildings){if(!b.geometry?.length)continue;const points=b.geometry.map(q=>localXY(q.lat,q.lon,p.lat,p.lon));let near=null;for(let i=0;i<points.length;i++){const t=segmentCross([0,0],endpoint,points[i],points[(i+1)%points.length]);if(t!==null&&t*len>3&&(near===null||t*len<near))near=t*len}if(near===null)continue;checked++;const h=height(b.tags||{});if(h===null)unknown++;else if(h>near*Math.tan(alt*Math.PI/180))blocks.push({distance:Math.round(near),height:Math.round(h)})}return {status:blocks.length?'blocked':unknown?'uncertain':'clear',blocked:blocks.length,unknown,checked,first:blocks.sort((a,b)=>a.distance-b.distance)[0]}}
function renderPlaces(){const box=$('#places');if(!state.places.length){box.innerHTML='<p class="muted">No suggested spaces yet. Use your location to search.</p>';return}box.innerHTML=state.places.filter(p=>p.here).concat(state.places.filter(p=>!p.here)).map((p,i)=>`<article class="place"><div><span class="rank">${i+1}</span><strong>${esc(p.name)}</strong><p>${p.here?(state.lang==='he'?'בדקו את השמים מחוץ למבנה':'Check sky from outside the building'):Math.round(p.dist)+(state.lang==='he'?' מ׳ מכאן · ':' m away · ')+esc(state.lang==='he'?t(p.kind,'he'):p.kind)+' · '+esc(p.direction)+(state.lang==='he'?' ממיקומכם':' from you')}</p><p class="sight">${esc(p.sightText||'Sightline not checked')}</p></div><span class="place-links"><a target="_blank" rel="noopener" href="https://www.google.com/maps/@?api=1&map_action=map&center=${p.lat}%2C${p.lon}&zoom=19&basemap=satellite">${state.lang==='he'?'לוויין ↗':'Satellite ↗'}</a><a target="_blank" rel="noopener" href="${mapLink(p)}">${state.lang==='he'?'ניווט ↗':'Navigate ↗'}</a></span></article>`).join('');localizeDynamic()}
const overpassHosts=[
 'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
 'https://overpass.private.coffee/api/interpreter',
 'https://overpass.kumi.systems/api/interpreter'
];
async function overpass(query){
 const failures=[];
 for(const host of overpassHosts){
   const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),26000);
   try{
     const response=await fetch(host+'?data='+encodeURIComponent(query),{signal:controller.signal});
     if(!response.ok)throw Error(`HTTP ${response.status}`);
     const result=await response.json();if(!Array.isArray(result.elements)||result.remark)throw Error(result.remark||'Invalid map response');
     return result;
   }catch(error){failures.push(`${new URL(host).hostname} ${error.name==='AbortError'?'timeout':error.message}`)}
   finally{clearTimeout(timer)}
 }
 console.warn('Overpass mirrors failed:',failures);throw Error('Map sources temporarily unavailable');
}
async function findPlaces(){if(!state.coords)return;const {lat,lon}=state.coords;
 const here={lat,lon,name:state.lang==='he'?'המיקום הנוכחי':'Current position',kind:'current position',dist:0,direction:'',here:true};
 state.places=[here];$('#place-status').textContent=state.lang==='he'?'בודקים רחובות קרובים ומבנים במפה. החיפוש עשוי להימשך עד דקה…':'Checking nearby streets, then mapped buildings. This can take up to a minute…';renderPlaces();
 try{
   const query=`[out:json][timeout:16];(way[highway~"^(footway|pedestrian|residential|living_street|path)$"](around:320,${lat},${lon});way[leisure~"^(park|garden|recreation_ground)$"](around:500,${lat},${lon});way[landuse~"^(grass|meadow|recreation_ground)$"](around:500,${lat},${lon}););out center 120;`;
   const data=await overpass(query),seen=new Set();
   const mapped=data.elements.map(e=>{const t=e.tags||{},p=e.center||e;const street=!!t.highway;return {...p,name:t.name||t['name:en']||(street?'Nearby street':({park:'Park',garden:'Garden',recreation_ground:'Recreation ground',grass:'Open grass',meadow:'Meadow'}[t.leisure||t.landuse]||'Open area')),kind:street?'street':t.leisure||t.landuse||'open area',dist:distance(lat,lon,p.lat,p.lon),direction:bearingName(bearing(lat,lon,p.lat,p.lon)),access:t.access,opening_hours:t.opening_hours}}).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&p.dist>20&&p.dist<700&&p.access!=='private'&&p.access!=='no'&&(!p.opening_hours||!p.opening_hours.includes('sunrise-sunset'))).filter(p=>{const key=Math.round(p.lat*2000)+','+Math.round(p.lon*2000);if(seen.has(key))return false;seen.add(key);return true}).sort((a,b)=>(a.kind==='street'?0:1)-(b.kind==='street'?0:1)||a.dist-b.dist).slice(0,3);
   state.places=[here,...mapped];renderPlaces();$('#place-status').textContent=state.lang==='he'?'נמצאו מקומות קרובים. בודקים כעת את המבנים…':'Nearby places found. Checking mapped buildings…';
 }catch(e){$('#place-status').textContent=state.lang==='he'?'חיפוש הרחובות אינו זמין. בודקים את המקום הנוכחי בלבד.':'Street search unavailable; checking your current position only.'}
 try{const centers=state.places.map(p=>`way[building](around:240,${p.lat},${p.lon});`).join('');const buildings=await overpass(`[out:json][timeout:30];(${centers});out geom 900;`);state.buildings=buildings.elements;const moon=sky();state.places=state.places.map(p=>{const sight=moon?sightline(p,moon.az,moon.alt):null;p.sight=sight;p.sightText=state.lang==='he'?( !sight?'קו הראייה לא נבדק':sight.status==='below'?'הלבנה מתחת לאופק':sight.status==='blocked'?`מבנה במפה חוסם את כיוון הלבנה (${sight.first.distance} מ׳; גובה מסומן ~${sight.first.height} מ׳)`:sight.status==='uncertain'?`אין חוסם ידוע, אך ל־${sight.unknown} מבנים חסרים נתוני גובה`:'לא נמצא מבנה במפה שחוסם את כיוון הלבנה בטווח 220 מטר') : !sight?'No sightline':sight.status==='below'?'Moon below horizon':sight.status==='blocked'?`Mapped building blocks the projected moon line (${sight.first.distance} m away; tagged height ~${sight.first.height} m)` : sight.status==='uncertain'?`No known blocker, but ${sight.unknown} building(s) lack height data`:'No mapped building blocks the moon line within 220 m';return p}).sort((a,b)=>Number(b.here)-Number(a.here)||({clear:0,uncertain:1,below:2,blocked:3}[a.sight?.status]??4)-({clear:0,uncertain:1,below:2,blocked:3}[b.sight?.status]??4)||(a.kind==='street'?0:1)-(b.kind==='street'?0:1)||a.dist-b.dist);$('#place-status').textContent=state.lang==='he'?`נבדקו ${state.buildings.length} מבנים במפה לידכם. הבדיקה מתבססת על גבולות וגבהים של מבנים ב־OSM בכיוון הלבנה, בטווח 220 מטר. גבהים חסרים, עצים ושטח עשויים לשנות את התוצאה. בדקו בפועל בחוץ.`:`Checked ${state.buildings.length} mapped buildings. Sightline uses OSM footprints and tagged heights within 220 m. Missing heights, trees and terrain may change the result. Check outdoors.`;renderPlaces()}
 catch(e){$('#place-status').textContent=state.lang==='he'?'נתוני מבנים אינם זמינים כרגע. כיווני הראייה לא אומתו; בדקו בשטח.':'Building data unavailable. Sightlines unverified; check outdoors.';state.places.forEach(p=>p.sightText=state.lang==='he'?'לא נבדק':'Not checked');renderPlaces()}
}

function locate(){if(!navigator.geolocation){$('#place-status').textContent='Geolocation is unavailable in this browser.';return}$('#place-status').textContent='Waiting for location permission…';navigator.geolocation.getCurrentPosition(p=>{state.coords={lat:p.coords.latitude,lon:p.coords.longitude};state.locationTimezone=null;state.forecast=null;state.forecastCoords=null;state.clearSkyCandidates=null;if(state.alertEnabled)localStorage.setItem('levana-alert-coords',JSON.stringify(state.coords));renderClearSky();$('#position').textContent=`${state.lang==='he'?'ליד':'Near'} ${state.coords.lat.toFixed(3)}, ${state.coords.lon.toFixed(3)} · accuracy ±${Math.round(p.coords.accuracy)} m`;renderTime();loadForecast();findPlaces()},e=>{$('#place-status').textContent='Location unavailable: '+e.message+'. You can enter coordinates below.'},{enableHighAccuracy:true,timeout:14000,maximumAge:60000})}
const whatsAppText='שלום עליכם';
const whatsAppQuery='?text=%D7%A9%D7%9C%D7%95%D7%9D+%D7%A2%D7%9C%D7%99%D7%9B%D7%9D';
function contactPhone(raw){const digits=String(raw||'').replace(/\D/g,'');return /^[1-9]\d{7,14}$/.test(digits)?digits:null}
function renderContacts(){const box=$('#contacts');box.innerHTML=state.selected.map((c,i)=>{const number=contactPhone(c.phone);return `<div class="contact"><div><b>${i+1}. ${esc(c.name||c.phone||'Person')}</b><small>${esc(c.phone||'No number')}</small></div><div class="contact-actions">${number?`<a href="tel:+${number}" aria-label="${state.lang==='he'?'התקשרו אל':'Call'} ${esc(c.name||c.phone)}">${state.lang==='he'?'התקשרו':'Call'}</a><a target="_blank" rel="noopener" href="https://wa.me/${number}${whatsAppQuery}" aria-label="${state.lang==='he'?'הודעת WhatsApp אל':'WhatsApp message to'} ${esc(c.name||c.phone)}">${state.lang==='he'?'הודעה ב-WhatsApp':'Message on WhatsApp'}</a>`:''}<button data-remove="${i}" aria-label="${state.lang==='he'?'הסרת':'Remove'} ${esc(c.name||c.phone||'person '+(i+1))}">×</button></div></div>`}).join('');$('#contact-count').textContent=`${state.selected.length}/3 ${state.lang==='he'?'אנשים נבחרו':'people selected'}`;box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.selected.splice(+b.dataset.remove,1);renderContacts()})}
async function pickContacts(){if(!navigator.contacts?.select){$('#contact-note').textContent='Contact Picker is not supported here. Add a number manually or use Share.';return}try{const picked=await navigator.contacts.select(['name','tel'],{multiple:true});for(const p of picked){if(state.selected.length>=3)break;let phone=p.tel?.[0]||'';if(!state.selected.some(c=>c.phone===phone&&phone))state.selected.push({name:p.name?.[0]||'',phone})}renderContacts()}catch(e){$('#contact-note').textContent='Could not open contacts. You can add numbers manually.'}}
